//! The event tree: every `Topic` enum generated by [`events!`](crate::events)
//! walks one level down with [`Node::step`].

use std::any::Any;
use std::fmt::{self, Display};
use std::hash::{Hash, Hasher};

/// Implemented by every enum generated with [`events!`](crate::events).
pub trait Node: Any + Send + Sync {
    #[doc(hidden)]
    fn step(&self) -> Step<'_>;
}

#[doc(hidden)]
pub struct Step<'a> {
    pub name: &'static str,
    /// Looked up by value in the interest graph, so publishing doesn't format it.
    pub param: Option<&'a dyn ParamValue>,
    /// `None` on a leaf.
    pub next: Option<&'a dyn Node>,
}

/// A type that can be a parameter in [`events!`](crate::events): `Display` for
/// [`subject`], `Eq` and `Hash` to route on the value itself.
///
/// Implemented for every `Clone + Eq + Hash + Display + Send + Sync + 'static`
/// type. Floats aren't `Eq`, so they can't be parameters.
#[diagnostic::on_unimplemented(
    message = "`{Self}` can't be a parameter",
    note = "parameters must implement `Clone + Eq + Hash + Display + Send + Sync + 'static`"
)]
pub trait ParamValue: Display + Send + Sync + 'static {
    #[doc(hidden)]
    fn as_any(&self) -> &dyn Any;
    #[doc(hidden)]
    fn eq_value(&self, other: &dyn ParamValue) -> bool;
    #[doc(hidden)]
    fn hash_value(&self, state: &mut dyn Hasher);
}

impl<V: Clone + Eq + Hash + Display + Send + Sync + 'static> ParamValue for V {
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn eq_value(&self, other: &dyn ParamValue) -> bool {
        other.as_any().downcast_ref::<V>() == Some(self)
    }
    fn hash_value(&self, mut state: &mut dyn Hasher) {
        self.hash(&mut state);
    }
}

impl PartialEq for dyn ParamValue {
    fn eq(&self, other: &Self) -> bool {
        self.eq_value(other)
    }
}

impl Eq for dyn ParamValue {}

impl Hash for dyn ParamValue {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.hash_value(state);
    }
}

/// NATS-style subject of an event, e.g. `user.<uuid>.delete`.
pub fn subject(node: &dyn Node) -> String {
    Subject(node).to_string()
}

/// Displays the [`subject`] of an event without building a `String`.
pub(crate) struct Subject<'a>(pub(crate) &'a dyn Node);

impl Display for Subject<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut next = Some(self.0);
        let mut first = true;
        while let Some(node) = next {
            let step = node.step();
            if !first {
                f.write_str(".")?;
            }
            first = false;
            f.write_str(step.name)?;
            if let Some(param) = step.param {
                write!(f, ".{param}")?;
            }
            next = step.next;
        }
        Ok(())
    }
}
